import modin.pandas as pd
import pandas

# mixed types, axis=1 should raise like pandas
df2 = pd.DataFrame({"a": [1, 2], "b": ["x", "y"]})
pdf2 = pandas.DataFrame({"a": [1, 2], "b": ["x", "y"]})
for fn in ("idxmax", "idxmin"):
    for f, pf in ((df2, pdf2),):
        try:
            getattr(f, fn)(axis=1)
            m = "no error"
        except TypeError as e:
            m = f"TypeError: {e}"
        try:
            getattr(pf, fn)(axis=1)
            p = "no error"
        except TypeError as e:
            p = f"TypeError"
        print(fn, "axis=1 mixed:", m, "| pandas:", p)

# all-NA / skipna behavior on strings
df3 = pd.DataFrame([["a", None], ["b", "c"]])
pdf3 = pandas.DataFrame([["a", None], ["b", "c"]])
for axis in (0, 1):
    for skipna in (True, False):
        try:
            r = getattr(df3, "idxmax")(axis=axis, skipna=skipna)
            pr = getattr(pdf3, "idxmax")(axis=axis, skipna=skipna)
            assert list(r.fillna(-99)) == list(pr.fillna(-99)), (r, pr)
        except ValueError:
            try:
                getattr(pdf3, "idxmax")(axis=axis, skipna=skipna)
                print("MISMATCH: modin raised, pandas didn't", axis, skipna)
            except ValueError:
                pass
print("edge OK")
